public class Animal {
    public void makeNoise() { System.out.println("Animal 叫"); }
    public void eat()       { System.out.println("Animal 吃"); }
    public void sleep()     { System.out.println("Animal 睡"); }
    public void roam()      { System.out.println("Animal 游荡"); }
}
public class Canine extends Animal {
    @Override public void roam() { System.out.println("Canine 成群游荡"); }
}
public class Wolf extends Canine {
    @Override public void makeNoise() { System.out.println("Wolf 嚎叫"); }
    @Override public void eat() { System.out.println("Wolf 撕咬"); }
}

// 逐方法追踪（最低者获胜）：
Wolf w = new Wolf();
w.makeNoise();   // Wolf 嚎叫   ← Wolf 层就找到，第一个匹配即停止
w.roam();        // Canine 成群游荡 ← Wolf 没有，往上到 Canine 找到
w.eat();         // Wolf 撕咬   ← Wolf 层找到
w.sleep();       // Animal 睡   ← Wolf、Canine 都没有，退到 Animal

