// 用「子类能否无缝替换父类」推导三条规则
class Parent {
    public Object make() { return new Object(); }   // 返回 Object
    public void take(Object o) { }                  // 参数 Object
}

class Child extends Parent {
    // ✓ 返回可协变（变具体）：String IS-A Object
    @Override public String make() { return "ok"; }

    // ✗ 参数不可变窄：调用方可能传任何 Object，不只是 String
    // @Override public void take(String s) { }
    // 这其实只是重载，不是覆盖！多态调用 take(Object) 时跑不到它
    @Override public void take(Object o) { }        // ✓ 正确的覆盖：参数照抄
}

// 关键不对称：
// 返回 = 我给你的 → 给得更具体可以（协变）
// 参数 = 你给我的 → 要求得更具体不行（必须照抄）

// 里氏替换原则：任何用 Parent 的地方换成 Child 都应照样正确
Parent p = new Child();
p.take(new Integer(1));   // 按 Parent 合同传 Object，Child 必须接得住

