// 关键：设备（对象）不变，遥控器（引用）可换
// 引用类型越具体，能看到的能力越完整

import java.util.ArrayList;

public class GenericDemo {
    public static void main(String[] args) {
        // 泛型版本：取出来就是 Dog，编译器替你转换
        ArrayList<Dog> dogList = new ArrayList<Dog>();
        dogList.add(new Dog());
        // dogList.add(new Cat());   // 编译期就被拦住
        Dog d = dogList.get(0);      // 不需要强制转换

        // Object 版本：取出来是 Object，必须自己转
        ArrayList<Object> objList = new ArrayList<Object>();
        objList.add(new Dog());
        // Dog d2 = objList.get(0);         // 编译失败
        Dog d2 = (Dog) objList.get(0);      // 自己转，转错就 ClassCastException
    }
}

